// ===========================================================================
// SKENARIO 1: KENDALI LOKAL MANDIRI (Mekanisme Otonom via Worker Scope)
// ===========================================================================
// Digunakan saat widget mengontrol fase transisinya sendiri secara independen
// melalui parameter instansiasi 'control' tanpa perlu registrasi ke objek luar.
AnimationWidget(
  // Prapasang cerdas: otomatis melesat dari bawah ke tengah (0.0 ke 1.0)
  inEffect: AnimationEffect.slideUp(duration: const Duration(milliseconds: 500)),
  // Prapasang cerdas: otomatis melesat dari tengah meneruskan ke atas (1.0 ke 0.0)
  outEffect: AnimationEffect.slideUp(duration: const Duration(milliseconds: 400)),
  child: (control) {
    return ElevatedButton(
      style: ElevatedButton.styleFrom(
        padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
      ),
      child: const Text('EKSEKUSI LOKAL'),
      onPressed: () async {
        // Memicu fase transisi keluar. Proteksi Mutex internal langsung mengunci status
        // untuk memblokir interaksi input susulan dari pengguna selama animasi berjalan.
        await control.playOut();

        // Jeda penundaan asinkronus untuk simulasi penanganan logika bisnis (misal: Hit API)
        await Future.delayed(const Duration(seconds: 2));

        // Mengembalikan visual widget ke kondisi utuh di layar setelah proses data selesai.
        await control.playIn();
      },
    );
  },
)

// ===========================================================================
// SKENARIO 2: INISIALISASI INSTANCE REMOTE CONTROLLER
// ===========================================================================
// Deklarasikan objek pengontrol ini di level Stateful Widget utama atau scope State Management
// untuk mengoordinasikan siklus hidup transisi banyak widget secara terpusat dan paralel.
final AnimationRemote remoteController = AnimationRemote();

// ===========================================================================
// SKENARIO 3: REGISTRASI KOMPONEN KE SISTEM REMOTE (GLOBAL & GROUP ID)
// ===========================================================================
// Komponen mendaftarkan referensi status internalnya secara otomatis ke objek 'remote'
// saat initState() dijalankan dan membersihkannya secara mandiri saat dispose().
Column(
  children: [
    // Elemen A: Terdaftar sebagai komponen Global karena properti 'id' dikosongkan (null)
    AnimationWidget(
      remote: remoteController,
      inEffect: AnimationEffect.fade(),
      outEffect: AnimationEffect.fade(),
      child: (control) => const Card(child: Text('KOMPONEN GLOBAL ALPHA')),
    ),

    // Elemen B: Dikelompokkan ke dalam klaster identifikasi grup 'auth_fields'
    AnimationWidget(
      remote: remoteController,
      id: 'auth_fields',
      // Masuk dari kanan ke tengah, lalu keluar meneruskan ke kiri (Continuous Momentum)
      inEffect: AnimationEffect.slideLeft(),
      outEffect: AnimationEffect.slideLeft(),
      child: (control) => const TextField(decoration: InputDecoration(labelText: 'USERNAME')),
    ),

    // Elemen C: Dimasukkan ke dalam kelompok 'auth_fields' yang sama dengan Elemen B
    AnimationWidget(
      remote: remoteController,
      id: 'auth_fields',
      inEffect: AnimationEffect.slideLeft(),
      outEffect: AnimationEffect.slideLeft(),
      child: (control) => const TextField(decoration: InputDecoration(labelText: 'PASSWORD')),
    ),

    // Elemen D: Diisolasi ke dalam kelompok identifikasi grup terpisah 'banner_ads'
    AnimationWidget(
      remote: remoteController,
      id: 'banner_ads',
      inEffect: AnimationEffect.zoomIn(),
      outEffect: AnimationEffect.zoomIn(),
      child: (control) => const Container(height: 100, color: Colors.blue),
    ),
  ],
)

// ===========================================================================
// SKENARIO 4: ORKESTRASI PEMICUAN TRANSISI ASINKRONUS VIA REMOTE CONTROLLER
// ===========================================================================
// Memanfaatkan pemrosesan Future.wait() di dalam engine untuk mengeksekusi subset kumpulan
// widget secara paralel tanpa risiko tabrakan state visual.
Row(
  children: [
    ElevatedButton(
      child: const Text('TRIGGER GLOBAL (SEMUA WIDGET)'),
      onPressed: () async {
        // Memerintahkan SELURUH widget yang terikat pada instance 'remoteController' 
        // (Elemen A, B, C, dan D) untuk memainkan animasi keluar secara serempak.
        await remoteController.playOut();
        await Future.delayed(const Duration(seconds: 1));
        // Mengembalikan seluruh elemen terdaftar ke kondisi visual utuh di layar.
        await remoteController.playIn();
      },
    ),
    ElevatedButton(
      child: const Text('TRIGGER BY ID (HANYA GRUP AUTH)'),
      onPressed: () async {
        // Melakukan filter registri untuk hanya memicu transisi keluar pada Elemen B dan C.
        // Elemen A dan Elemen D sama sekali tidak akan terpengaruh oleh pemicu ini.
        await remoteController.playOut('auth_fields');
        await Future.delayed(const Duration(milliseconds: 500));
        // Hanya memunculkan kembali kelompok kolom input autentikasi ke layar.
        await remoteController.playIn('auth_fields');
      },
    ),
    ElevatedButton(
      child: const Text('TRIGGER BY ID (HANYA GRUP BANNER)'),
      onPressed: () async {
        // Melakukan penargetan eksklusif untuk mengeksekusi transisi keluar hanya pada Elemen D.
        await remoteController.playOut('banner_ads');
        await Future.delayed(const Duration(seconds: 1));
        // Mengembalikan elemen spanduk iklan ke layar secara presisi.
        await remoteController.playIn('banner_ads');
      },
    ),
  ],
)

