    // 2. Ubah pesan loading di tengah proses tanpa memblokir UI
    loader.message('Mengunduh aset dari server...');
    await Future.delayed(const Duration(seconds: 2));

    loader.message('Menyimpan ke memori lokal...');
    await Future.delayed(const Duration(seconds: 1));

  } catch (e) {
    print('Terjadi kesalahan: $e');
  } finally {
    // 3. Wajib panggil close() di finally agar layar tidak hang
    loader.close();
  }
}

